/* =============================================================================
   REG-06 · Crea tu frase de seguridad — estilos.
   Única fuente de color: los tokens de `tokens.css`. Aquí no hay un solo hex.
   ========================================================================== */

.screen {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 52px var(--bw-pad-panel) 56px;
}

.column {
  width: 100%;
  max-width: 600px;
}

/* ── Indicador de los cuatro pasos ───────────────────────────────────────── */

.steps {
  display: flex;
  align-items: center;
  list-style: none;
  padding: 0;
  margin: 0 0 36px;
}

.step {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  white-space: nowrap;
}

.step:not(:last-child) {
  flex: 1;
}

.stepDot {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--bw-size-hint);
  font-weight: 600;
  flex-shrink: 0;
}

.stepLabel {
  line-height: 1;
}

.stepLine {
  flex: 1;
  height: 1px;
  min-width: 12px;
  margin: 0 10px;
  background: var(--bw-line-steel);
}

.stepDone .stepDot {
  background: var(--bw-brass);
  color: var(--bw-cold-white);
}

.stepDone .stepLabel {
  color: var(--bw-brass);
}

.stepActive .stepDot {
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
}

.stepActive .stepLabel {
  color: var(--bw-calibration-blue);
}

.stepPending .stepDot {
  background: var(--bw-cold-white);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-line-steel-strong);
}

.stepPending .stepLabel {
  color: var(--bw-input-placeholder);
}

/* ── Encabezado ──────────────────────────────────────────────────────────── */

.eyebrow {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: var(--bw-size-eyebrow);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-brass);
  margin: 0 0 10px;
}

.title {
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: var(--bw-size-title);
  letter-spacing: var(--bw-ls-title);
  line-height: 1.25;
  color: var(--bw-deep-steel);
  margin: 0 0 8px;
}

.subtitle {
  font-size: var(--bw-size-body);
  line-height: 1.6;
  color: var(--bw-steel-mist);
  margin: 0 0 32px;
}

/* ── Campos ──────────────────────────────────────────────────────────────── */

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 20px;
}

.label {
  font-size: var(--bw-size-label);
  font-weight: 500;
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-ink-steel);
}

.inputWrap {
  position: relative;
  display: flex;
}

.input {
  box-sizing: border-box;
  width: 100%;
  padding: 10px 40px 10px 13px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-input);
  letter-spacing: 0.05em;
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.input::placeholder {
  color: var(--bw-input-placeholder);
  letter-spacing: normal;
}

.input:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.input.inputOk {
  border-color: var(--bw-signal-green);
}

.input.inputError {
  border-color: var(--bw-danger);
}

.eye {
  position: absolute;
  right: 11px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  padding: 2px;
  background: none;
  border: none;
  color: var(--bw-steel-mist);
  cursor: pointer;
  transition: color 0.12s;
}

.eye:hover {
  color: var(--bw-deep-steel);
}

/* ── Barra de fortaleza de cinco segmentos ───────────────────────────────── */

.strength {
  margin-top: 8px;
}

.strengthBar {
  display: flex;
  gap: 3px;
  margin-bottom: 5px;
}

.segment {
  flex: 1;
  height: 4px;
  border-radius: 2px;
  background: var(--bw-line-steel);
  transition: background 0.25s;
}

.segment[data-on='true'][data-level='muy-debil'] {
  background: var(--bw-danger);
}

.segment[data-on='true'][data-level='debil'] {
  background: var(--bw-strength-weak);
}

.segment[data-on='true'][data-level='aceptable'] {
  background: var(--bw-strength-fair);
}

.segment[data-on='true'][data-level='fuerte'] {
  background: var(--bw-strength-good);
}

.segment[data-on='true'][data-level='muy-fuerte'] {
  background: var(--bw-signal-green);
}

.strengthLabel {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  font-weight: 500;
  color: var(--bw-input-placeholder);
  transition: color 0.25s;
}

.strengthLabel[data-level='muy-debil'] {
  color: var(--bw-danger);
}

.strengthLabel[data-level='debil'] {
  color: var(--bw-strength-weak);
}

.strengthLabel[data-level='aceptable'] {
  color: var(--bw-strength-fair);
}

.strengthLabel[data-level='fuerte'] {
  color: var(--bw-strength-good);
}

.strengthLabel[data-level='muy-fuerte'] {
  color: var(--bw-signal-green);
}

/* ── Mensajes de error y aviso ───────────────────────────────────────────── */

.error {
  font-size: 12px;
  color: var(--bw-error-text);
  margin: 2px 0 0;
}

.notice {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 12px 14px;
  border-left: 3px solid var(--bw-brass);
  border-radius: 0 4px 4px 0;
  background: var(--bw-tag-bg);
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  margin-bottom: 24px;
}

.notice p {
  margin: 0;
}

.notice strong {
  /* El HTML aprobado tinta el `<strong>` con un latón oscurecido (#92702e) que no
     tiene token propio: se usa el latón base, el más cercano de la paleta. */
  color: var(--bw-brass);
  font-weight: 600;
}

.noticeIcon {
  display: flex;
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--bw-brass);
}

/* ── Casilla de confirmación de consecuencias ────────────────────────────── */

.checkbox {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 16px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-size: 13px;
  line-height: 1.55;
  color: var(--bw-ink-steel);
  margin-bottom: 24px;
  cursor: pointer;
  user-select: none;
}

.checkbox input {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  margin: 1px 0 0;
  accent-color: var(--bw-calibration-blue);
  cursor: pointer;
}

/* ── Botón principal ─────────────────────────────────────────────────────── */

.primary {
  box-sizing: border-box;
  width: 100%;
  padding: 13px 20px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  color: var(--bw-cold-white);
  cursor: pointer;
  transition: opacity 0.15s;
}

.primary:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.primary:not(:disabled):hover {
  opacity: 0.9;
}

import { useRef, useState } from 'react';
import type { ChangeEvent, FormEvent } from 'react';

import type { MemberProfile } from '../../lib/session';
import {
  EMPTY_PASSPHRASE_FORM,
  PASSPHRASE_TEXTS as T,
  checkPassphrase,
  passphraseView,
} from '../../lib/passphrase';
import type { PassphraseCheck, PassphraseForm } from '../../lib/passphrase';

import styles from './BackupPassphrase.module.css';

interface Props {
  /** El miembro en registro: su email compara contra la contraseña de acceso y sus datos penalizan la frase. */
  profile: MemberProfile;
  /** Entrega la frase al wiring de REG-07, en memoria. La frase no sale del navegador. */
  onContinue: (passphrase: string) => void;
}

/** Icono de verificación, en `currentColor`: lo tiñe el disco de latón que lo envuelve. */
function CheckIcon() {
  return (
    <svg
      aria-hidden="true"
      width="11"
      height="11"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2.5}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <polyline points="20 6 9 17 4 12" />
    </svg>
  );
}

/** Ojo abierto: la frase está oculta — pulsarlo la revela. */
function EyeIcon() {
  return (
    <svg
      aria-hidden="true"
      width="15"
      height="15"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.8}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
      <circle cx="12" cy="12" r="3" />
    </svg>
  );
}

/** Ojo tachado: la frase está a la vista — pulsarlo la vuelve a ocultar. */
function EyeOffIcon() {
  return (
    <svg
      aria-hidden="true"
      width="15"
      height="15"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.8}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
      <line x1="1" y1="1" x2="23" y2="23" />
    </svg>
  );
}

/** Triángulo de advertencia del aviso. */
function WarningIcon() {
  return (
    <svg
      aria-hidden="true"
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.8}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
      <line x1="12" y1="9" x2="12" y2="13" />
      <line x1="12" y1="17" x2="12.01" y2="17" />
    </svg>
  );
}

/**
 * REG-06 · Crea tu frase de seguridad (backup passphrase).
 *
 * Segunda pantalla de la Fase B: recoge la frase que protegerá la copia cifrada de
 * la clave privada. La mide en local con `checkPassphrase` (zxcvbn + huella de la
 * contraseña de acceso, ambas en memoria) y la entrega al wiring en el `onContinue`.
 *
 * Invariante *server-blind* (ADR-001): aquí no hay una sola llamada a la red. La
 * frase vive en el estado de React y en los `<input>`: no se pinta en ningún texto,
 * ni en un `title`, ni en un `data-*`, ni se persiste en storage ni en cookies. El
 * par de claves y el backup cifrado son REG-07.
 *
 * Toda la vista se deriva de `passphraseView(form, check)`: el botón sólo avanza con
 * frase fuerte (score ≥ 3 y 12 caracteres), repetición coincidente y casilla marcada.
 */
export function BackupPassphrase({ profile, onContinue }: Props) {
  const [form, setForm] = useState<PassphraseForm>(EMPTY_PASSPHRASE_FORM);
  const [check, setCheck] = useState<PassphraseCheck | null>(null);
  const [showPassphrase, setShowPassphrase] = useState(false);
  const [showRepeat, setShowRepeat] = useState(false);

  /** La última frase tecleada: descarta la medida de una pulsación anterior. */
  const latestPassphrase = useRef('');

  const view = passphraseView(form, check);
  const strength = view.strength;

  function handlePassphraseChange(event: ChangeEvent<HTMLInputElement>) {
    const value = event.target.value;
    latestPassphrase.current = value;
    setForm((previous) => ({ ...previous, passphrase: value }));
    checkPassphrase(profile.email, value, [profile.fullName ?? '', profile.orgName])
      .then((result) => {
        // Una respuesta desordenada no puede pisar la medida de la frase actual.
        if (result.passphrase === latestPassphrase.current) setCheck(result);
      })
      .catch(() => {
        // Medida local que no ha llegado: sin barra y con el botón bloqueado, nada más que hacer.
      });
  }

  function handleRepeatChange(event: ChangeEvent<HTMLInputElement>) {
    const value = event.target.value;
    setForm((previous) => ({ ...previous, repeat: value }));
  }

  function handleAcknowledgedChange(event: ChangeEvent<HTMLInputElement>) {
    const acknowledged = event.target.checked;
    setForm((previous) => ({ ...previous, acknowledged }));
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (view.canContinue) onContinue(form.passphrase);
  }

  const passphraseClass = view.passphraseError
    ? styles.inputError
    : view.passphraseOk
      ? styles.inputOk
      : '';
  const repeatClass = view.repeatError ? styles.inputError : view.repeatOk ? styles.inputOk : '';

  return (
    <div className={styles.screen}>
      <div className={styles.column}>
        <form noValidate onSubmit={handleSubmit}>
          {/* Los cuatro pasos del registro: los dos primeros ya están hechos, este
              es el de Seguridad y la Activación todavía está pendiente. */}
          <ol className={styles.steps} aria-label="Pasos del registro">
            <li className={`${styles.step} ${styles.stepDone}`}>
              <span className={styles.stepDot}>
                <CheckIcon />
              </span>
              <span className={styles.stepLabel}>Solicitud</span>
              <span aria-hidden="true" className={styles.stepLine} />
            </li>
            <li className={`${styles.step} ${styles.stepDone}`}>
              <span className={styles.stepDot}>
                <CheckIcon />
              </span>
              <span className={styles.stepLabel}>Organización</span>
              <span aria-hidden="true" className={styles.stepLine} />
            </li>
            <li className={`${styles.step} ${styles.stepActive}`} aria-current="step">
              <span className={styles.stepDot}>3</span>
              <span className={styles.stepLabel}>Seguridad</span>
              <span aria-hidden="true" className={styles.stepLine} />
            </li>
            <li className={`${styles.step} ${styles.stepPending}`}>
              <span className={styles.stepDot}>4</span>
              <span className={styles.stepLabel}>Activación</span>
            </li>
          </ol>

          <p className={styles.eyebrow}>{T.eyebrow}</p>

          <h1 className={styles.title}>{T.title}</h1>

          <p className={styles.subtitle}>{T.subtitle}</p>

          <div className={styles.field}>
            <label className={styles.label} htmlFor="passphrase">
              {T.passphraseLabel}
            </label>
            <div className={styles.inputWrap}>
              <input
                id="passphrase"
                className={`${styles.input} ${passphraseClass}`}
                type={showPassphrase ? 'text' : 'password'}
                autoComplete="new-password"
                placeholder={T.passphrasePlaceholder}
                value={form.passphrase}
                onChange={handlePassphraseChange}
                aria-invalid={view.passphraseError ? 'true' : 'false'}
                aria-describedby={view.passphraseError ? 'passphrase-error' : undefined}
              />
              <button
                type="button"
                className={styles.eye}
                aria-label={showPassphrase ? T.hidePassphrase : T.showPassphrase}
                onClick={() => setShowPassphrase((visible) => !visible)}
              >
                {showPassphrase ? <EyeOffIcon /> : <EyeIcon />}
              </button>
            </div>

            {strength && (
              <div className={styles.strength}>
                <div className={styles.strengthBar}>
                  {[0, 1, 2, 3, 4].map((index) => (
                    <span
                      key={index}
                      data-testid="strength-segment"
                      data-on={index < strength.segments ? 'true' : 'false'}
                      data-level={strength.key}
                      className={styles.segment}
                    />
                  ))}
                </div>
                <span
                  data-testid="strength-label"
                  data-level={strength.key}
                  className={styles.strengthLabel}
                >
                  {strength.label}
                </span>
              </div>
            )}

            {view.passphraseError && (
              <p id="passphrase-error" className={styles.error}>
                {view.passphraseError}
              </p>
            )}
          </div>

          <div className={styles.field}>
            <label className={styles.label} htmlFor="repeat">
              {T.repeatLabel}
            </label>
            <div className={styles.inputWrap}>
              <input
                id="repeat"
                className={`${styles.input} ${repeatClass}`}
                type={showRepeat ? 'text' : 'password'}
                autoComplete="new-password"
                placeholder={T.repeatPlaceholder}
                value={form.repeat}
                onChange={handleRepeatChange}
                aria-invalid={view.repeatError ? 'true' : 'false'}
                aria-describedby={view.repeatError ? 'repeat-error' : undefined}
              />
              <button
                type="button"
                className={styles.eye}
                aria-label={showRepeat ? T.hidePassphrase : T.showPassphrase}
                onClick={() => setShowRepeat((visible) => !visible)}
              >
                {showRepeat ? <EyeOffIcon /> : <EyeIcon />}
              </button>
            </div>

            {view.repeatError && (
              <p id="repeat-error" className={styles.error}>
                {view.repeatError}
              </p>
            )}
          </div>

          <div className={styles.notice}>
            <span className={styles.noticeIcon}>
              <WarningIcon />
            </span>
            <p>
              <strong>{T.noticeStrong}</strong> {T.noticeRest}
            </p>
          </div>

          <label className={styles.checkbox}>
            <input
              type="checkbox"
              checked={form.acknowledged}
              onChange={handleAcknowledgedChange}
            />
            {T.acknowledgement}
          </label>

          <button type="submit" className={styles.primary} disabled={!view.canContinue}>
            {T.submit}
          </button>
        </form>
      </div>
    </div>
  );
}
